import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Draw panel outlines and interior blocks as given; partial final row/column are border only.
for pr,r0 in enumerate(starts):
  for pc,c0 in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<n and c<n and (dr in (0,4) or dc in (0,4)):
          g[r][c]=4
    if pr<4 and pc<4:
      col=colors[pr][pc]
      for dr in (1,2,3):
        for dc in (1,2,3): g[r0+dr][c0+dc]=col
# Join same-colored panel interiors along each panel row across only intervening separator columns.
for pr,r0 in enumerate(starts[:4]):
  for a in range(4):
    for b in range(a+1,4):
      if colors[pr][a]==colors[pr][b]:
        for r in range(r0+1,r0+4):
          for c in range(starts[a]+5,starts[b]): g[r][c]=colors[pr][a]
# Join same-colored panel interiors along each panel column across only intervening separator rows.
for pc in range(4):
  for a in range(4):
    for b in range(a+1,4):
      if colors[a][pc]==colors[b][pc]:
        for c in range(starts[pc]+1,starts[pc]+4):
          for r in range(starts[a]+5,starts[b]): g[r][c]=colors[a][pc]
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

