# For each repeated panel row, link equal-color objects only through separator gaps.
for pr,r0 in enumerate(starts[:4]):
  for color in set(colors[pr]):
    indices=[pc for pc in range(4) if colors[pr][pc]==color]
    if len(indices)>1:
      for pc in range(min(indices),max(indices)):
        # no stroke through an object; draw only the 2-column inter-panel gap
        for r in range(r0+1,r0+4):
          for c in range(starts[pc]+5,starts[pc+1]): g[r][c]=color
# For each repeated panel column, link equal-color objects only through separator gaps.
for pc in range(4):
  col=[colors[pr][pc] for pr in range(4)]
  for color in set(col):
    indices=[pr for pr in range(4) if col[pr]==color]
    if len(indices)>1:
      for pr in range(min(indices),max(indices)):
        for c in range(starts[pc]+1,starts[pc]+4):
          for r in range(starts[pr]+5,starts[pr+1]): g[r][c]=color
